/// "Activities" tab. Hosts the paged day/week/month/year bar chart
/// (`ActivityChartCard`) with an activity filter. Every bar is the UNION of
/// net shielded intervals (`NetEffectiveIntervals`) clipped to that bar:
/// device-wide pauses carved exactly where they occurred, overlapping sessions
/// counted once, so the "All" filter's chart TOTAL equals the Home/Block List
/// hero for the same window. The per-activity filter unions only that
/// activity's intervals. The page's terminal section is the past-7-days
/// top-activities list under the chart, whose rows drill into
/// `ActivityDetailView`.
struct ActivitiesTabView: View {
    /// Owned by `MainTabView`. Drives the NavigationStack so Settings can
    /// be popped on tab switch.
    @Binding var path: NavigationPath

    /// W7: the Activities tab is fed from the snapshot spine instead of loading
    /// the disk itself. EVERY chart input rides this one bundle: the raw
    /// (unfiltered, full-history) session arrays, the currently-running source
    /// the chart counts live, the install date, the content fingerprint, and the
    /// loaded flag, and the chart card windows the raw arrays internally per
    /// range. The only local state is the interactive filter selection.
    ///
    /// This tab deliberately holds no reference to the Block List's timeline
    /// bundle: those arrays are bounded to records overlapping TODAY (so that
    /// card's per-minute rebuild stays cheap), and reading them here made every
    /// window older than today total 0: the bug this severance closes.
    let tabsSpine: TabsSpineSnapshot
    /// Enforcement gaps (grant-emptied shield spans). Carved by the chart
    /// exactly like bypasses, so the Activities bars agree with every other
    /// gap-carved surface. Loose on the snapshot (only this tab reads it).
    let enforcementGaps: [EnforcementGap]
    let allActivities: [Activity]
    /// True only while this tab is selected and the scene is active, so the
    /// chart's live-tail minute tick does not run while the tab is hidden.
    let isLiveTicking: Bool

    /// Chart filter selection. nil = "All activities" (amber bars).
    @State private var selectedActivityID: UUID? = nil
    /// Incremented by a tap on anything here that is not a bar with data; the
    /// chart page clears its pin when it changes. A counter rather than the pin
    /// itself so the page keeps owning its state and its remount reset.
    @State private var pinClearToken = 0

    init(
        path: Binding<NavigationPath> = .constant(NavigationPath()),
        tabsSpine: TabsSpineSnapshot = .empty,
        enforcementGaps: [EnforcementGap] = [],
        allActivities: [Activity] = [],
        isLiveTicking: Bool = false
    ) {
        self._path = path
        self.tabsSpine = tabsSpine
        self.enforcementGaps = enforcementGaps
        self.allActivities = allActivities
        self.isLiveTicking = isLiveTicking
    }

    var body: some View {
        NavigationStack(path: $path) {
            ScrollView {
                VStack(alignment: .leading, spacing: 18) {
                    if tabsSpine.tabsLoaded {
                        ActivityChartCard(
                            blockSessions: tabsSpine.activitiesBlockSessions,
                            completedFocusSessions: tabsSpine.activitiesFocusSessions,
                            bypassEvents: tabsSpine.activitiesBypassEvents,
                            enforcementGaps: enforcementGaps,
                            allActivities: allActivities,
                            installDate: tabsSpine.activitiesInstallDate,
                            contentFingerprint: tabsSpine.activitiesFingerprint,
                            liveSource: tabsSpine.activitiesLiveSource,
                            isLiveTicking: isLiveTicking,
                            selectedActivityID: $selectedActivityID,
                            pinClearToken: pinClearToken
                        )
                        .padding(.horizontal, DS.Spacing.homeHorizontalMargin)
                        .padding(.top, DS.Spacing.homeTopPadding)

                        if !topGroups.isEmpty {
                            VStack(alignment: .leading, spacing: DS.Spacing.homeCardSpacing) {
                                // Section line between the chart's arrows
                                // above and this section: the seam minus the
                                // outer stack's 18pt spacing over it, the seam
                                // minus this stack's 14pt under it. Inside the
                                // branch, so a page with no top activities
                                // ends on the arrows.
                                DS.SectionLine()
                                    .padding(.top, DS.Spacing.sectionSeam - 18)
                                    .padding(.bottom, DS.Spacing.sectionSeam - DS.Spacing.homeCardSpacing)
                                pastSevenDaysHeader
                                pastSevenDaysList
                            }
                            .padding(.horizontal, DS.Spacing.homeHorizontalMargin)
                        }
                    } else {
                        ProgressView()
                            .controlSize(.regular)
                            .frame(maxWidth: .infinity, minHeight: 200)
                            .accessibilityLabel("Loading activity history")
                    }
                }
                .padding(.bottom, DS.Spacing.homeBottomPadding)
                // Tap-away for the chart's pin. Child gestures win, so buttons,
                // links, and the plot's own tap are untouched; a discrete tap
                // never blocks the scroll pan.
                .contentShape(Rectangle())
                .onTapGesture { pinClearToken += 1 }
            }
            .background(DS.Colors.pageBackground)
            .navigationTitle("")
            .navigationBarTitleDisplayMode(.inline)
            .navigationDestination(for: SettingsRoute.self) { _ in
                SettingsView()
            }
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    SettingsToolbarButton(path: $path)
                }
            }
            .refreshable {
                // W7: pull-to-refresh asks the spine to rebuild; fresh data
                // flows back in as props. The spine is off-main and not
                // awaitable from here, so the spinner dismisses immediately.
                NotificationCenter.default.post(name: .liveDataNeedsRefresh, object: nil)
            }
        }
    }

    // MARK: - Past 7 days top activities

    /// The rows the list renders. Zero-total groups are dropped, then the rest
    /// are capped at five: the same two steps the Home Top Activities card
    /// applies, so the section never shows a "0m" row and its header never
    /// counts past five. The spine deliberately keeps every group (the
    /// drill-ins read them), so the trim belongs here in the consumer.
    private var topGroups: [ActivityGroup] {
        Array(
            tabsSpine.timeSevenDayGroups
                .filter { $0.totalEffectiveSeconds > 0 }
                .prefix(5)
        )
    }

    /// "TOP 5 ACTIVITIES PAST 7 DAYS". The section is hidden when `topGroups`
    /// is empty, so the count is always at least 1 here.
    private var sevenDayHeaderText: String {
        let noun = topGroups.count == 1 ? "ACTIVITY" : "ACTIVITIES"
        return "TOP \(topGroups.count) \(noun) PAST 7 DAYS"
    }

    private var pastSevenDaysHeader: some View {
        Text(sevenDayHeaderText)
            .font(.caption2.weight(.semibold))
            .tracking(0.6)
            .foregroundStyle(.secondary)
    }

    private var pastSevenDaysList: some View {
        VStack(spacing: 0) {
            ForEach(Array(topGroups.enumerated()), id: \.element.id) { index, group in
                NavigationLink {
                    ActivityDetailView(
                        activityName: group.displayName,
                        totalEffectiveSeconds: group.totalEffectiveSeconds,
                        sessions: group.sessions
                    )
                } label: {
                    ActivitiesTabRow(group: group, rank: index)
                }
                .buttonStyle(.plain)
                .hapticTap()
                // Between rows only: this list ends the tab, and the page
                // reads better finishing on a row than on a line (user
                // direction 2026-09-14). Full width, like the section
                // hairlines above it.
                if index < topGroups.count - 1 {
                    Divider()
                        .overlay(DS.Colors.hairline)
                }
            }
        }
    }

    /// Position-based palette for the list above: `ActivitiesTabRow` tints its
    /// icon tile with this so a row's color matches the chart's position-based
    /// bar color for the same rank. Thin wrapper around
    /// `PositionPalette.color(rank:)`.
    static func positionColor(rank: Int) -> Color? {
        PositionPalette.color(rank: rank)
    }
}

