/// "Time" tab. Lists completed BlockSessions AND completed Quick Start
/// focus sessions finalized in the last 14 days (rolling, not
/// bucketed by calendar day) so the user can retroactively assign or
/// change the purpose of each entry. One line per session (`TimeTabRow`),
/// grouped under an uppercase day header. A currently-RUNNING scheduled block
/// is pinned at the top (editable the same way) so its purpose can be
/// changed MID-RUN: the edit re-tags the single occurrence, so the whole
/// block counts toward the new purpose when it finalizes.
///
/// Read-only of everything except `purposeActivityID` / purpose
/// snapshot, edited via `SessionPurposeEditorView` for either source
/// type via the shared picker.
struct TimeTabView: View {
    /// Owned by `MainTabView`. Drives the NavigationStack so Settings can be
    /// popped on tab switch.
    @Binding var path: NavigationPath

    /// W7: the Time tab is now fed from the snapshot spine (MainTabView's
    /// coalesced off-main build) instead of loading the disk itself. The tab
    /// spine bundle carries the rows and the loaded flag this tab renders, so
    /// a single build serves every tab, no per-tab `.liveDataNeedsRefresh`
    /// reload duplicating the same disk reads. The only local state is the
    /// editor presentation.
    let tabsSpine: TabsSpineSnapshot
    /// Activities catalog. Resolves each row's purpose into the activity its
    /// chip shows, and feeds the `SessionPurposeEditorView` sheet so the picker
    /// has the latest names when the user taps a chip.
    let activities: [Activity]

    @State private var editingRow: TimeRowSource?

    init(
        path: Binding<NavigationPath> = .constant(NavigationPath()),
        tabsSpine: TabsSpineSnapshot = .empty,
        activities: [Activity] = []
    ) {
        self._path = path
        self.tabsSpine = tabsSpine
        self.activities = activities
    }

    var body: some View {
        NavigationStack(path: $path) {
            content
                .background(DS.Colors.pageBackground)
                // The "Your time" title lives in the scroll content, so the
                // bar stays empty and inline here. The pushed Settings screen
                // keeps its own bar.
                .navigationTitle("")
                .navigationBarTitleDisplayMode(.inline)
                .navigationDestination(for: SettingsRoute.self) { _ in
                    SettingsView()
                }
                .toolbar {
                    ToolbarItem(placement: .topBarTrailing) {
                        settingsButton
                    }
                }
                .refreshable {
                    // W7: pull-to-refresh asks the spine to rebuild; fresh rows
                    // flow back in as props. The spine is off-main and not
                    // awaitable from here, so the spinner dismisses immediately.
                    NotificationCenter.default.post(name: .liveDataNeedsRefresh, object: nil)
                }
        }
        .sheet(item: $editingRow) { row in
            SessionPurposeEditorView(
                source: row,
                activities: activities
            ) {
                // `commit(selected:)` already posts `.liveDataNeedsRefresh`,
                // which drives the spine rebuild that re-feeds this tab. Just
                // dismiss here.
                editingRow = nil
            }
        }
    }

    /// This tab's gear is the mock's heavier glyph. It draws no circle of its
    /// own: iOS already gives a bar button item a round background, and a
    /// custom circle inside that one reads as a double ring (measured on the
    /// simulator: a 52pt system background around a 44pt custom circle). The
    /// size is the one that makes the glyph span about half that background,
    /// as it does in the mock (measured: a 24pt glyph box, the mock's 24pt).
    ///
    /// The shared `SettingsToolbarButton` (the lighter glyph every other tab
    /// shows) is deliberately left alone: a weight switch on a component four
    /// other tabs render would be a single-use abstraction.
    private var settingsButton: some View {
        Button {
            Haptics.fire(.tap)
            path.append(SettingsRoute.main)
        } label: {
            Image(systemName: "gearshape")
                .font(.system(size: 18, weight: .semibold))
                .foregroundStyle(DS.Colors.accent)
        }
        .accessibilityLabel("Settings")
    }

    private var content: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 0) {
                header

                if !tabsSpine.tabsLoaded {
                    ProgressView()
                        .controlSize(.regular)
                        .frame(maxWidth: .infinity, minHeight: 200)
                        .accessibilityLabel("Loading session history")
                        .padding(.top, TimeTabMetrics.dayHeaderTopSpacing)
                } else if !tabsSpine.timeRows.isEmpty {
                    daySections
                } else {
                    ContentUnavailableView {
                        Label("No sessions yet", systemImage: "clock")
                    } description: {
                        Text("Complete a focus session and it will show up here for the next 14 days.")
                    }
                    .padding(.top, TimeTabMetrics.dayHeaderTopSpacing)
                }
            }
            // The page inset lives on this VStack, never on the ScrollView:
            // padding the ScrollView would inset the scroll area itself, and
            // with it the refresh control.
            .padding(.horizontal, DS.Spacing.homeHorizontalMargin)
            .padding(.top, DS.Spacing.homeTopPadding)
            .padding(.bottom, DS.Spacing.homeBottomPadding)
        }
    }

    // MARK: - Header

    /// "Your time" over its subtitle, at the top of the scroll content. The
    /// gap below belongs to whatever follows (a day header, the spinner, or
    /// the empty state), so the header adds none of its own.
    private var header: some View {
        VStack(alignment: .leading, spacing: TimeTabMetrics.titleToSubtitleSpacing) {
            Text("Your time")
                .dsFixedFont(.system(size: 28, weight: .bold))
                .foregroundStyle(TimeTabPalette.textPrimary)
                .accessibilityAddTraits(.isHeader)
            Text("Tell us what you did instead. You can change anything from the past 14 days.")
                .dsFixedFont(.system(size: 15))
                .foregroundStyle(TimeTabPalette.subtitle)
                .fixedSize(horizontal: false, vertical: true)
        }
    }

    // MARK: - Sessions

    /// One line per session under an uppercase day header, with a faint line
    /// above every row. Grouping is derived at render time (not from the
    /// snapshot) so "Today"/"Yesterday" labels can't go stale: see
    /// `TimeDayGrouping`.
    private var daySections: some View {
        LazyVStack(alignment: .leading, spacing: 0) {
            ForEach(TimeDayGrouping.groups(rows: tabsSpine.timeRows)) { group in
                VStack(alignment: .leading, spacing: 0) {
                    dayHeader(group.label)
                    ForEach(group.rows) { row in
                        rowDivider
                        TimeTabRow(source: row, activity: activity(for: row)) {
                            editingRow = row
                        }
                    }
                }
            }
        }
    }

    private func dayHeader(_ label: String) -> some View {
        Text(label)
            .dsFixedFont(.system(size: 13, weight: .semibold))
            .textCase(.uppercase)
            .tracking(TimeTabMetrics.dayHeaderTracking)
            .foregroundStyle(TimeTabPalette.dayHeader)
            .padding(.top, TimeTabMetrics.dayHeaderTopSpacing)
            .padding(.bottom, TimeTabMetrics.dayHeaderBottomSpacing)
            .accessibilityAddTraits(.isHeader)
    }

    /// The mock's 1pt row border at 6% white: quieter than the 16%
    /// `DS.Hairline` the other flat tabs draw between their rows.
    private var rowDivider: some View {
        Rectangle()
            .fill(DS.Colors.overlayWhite06)
            .frame(height: 1)
    }

    /// The activity a row was tagged with, looked up by id so the chip shows
    /// its current name, emoji and color. Nil when the row has no purpose id
    /// or the id matches no activity (the row then falls back to the name
    /// saved on the session).
    private func activity(for row: TimeRowSource) -> Activity? {
        guard let purposeID = TimeDayGrouping.purposeActivityID(for: row) else { return nil }
        return activities.first { $0.id == purposeID }
    }
}

// MARK: - Palette and metrics

/// Exact dark literals from the Time tab mock
/// (`.claude/plans/assets/2026-09-24-time-vv4-mock.html`) for the colors no DS
/// token matches. Dark-only by design, like `SchedulePalette`. Internal, not
/// private, because `TimeTabRow` draws its text from the same tiers.
enum TimeTabPalette {
    /// CSS `--txt:#F5F5F7`: the "Your time" title and each row's length.
    static let textPrimary = Color(red: 0xF5 / 255, green: 0xF5 / 255, blue: 0xF7 / 255)
    /// CSS `--txt2:rgba(235,235,245,.6)`: the subtitle under the title.
    static let subtitle = Color(red: 235 / 255, green: 235 / 255, blue: 245 / 255).opacity(0.6)
    /// Each row's time. The mock draws it in the same 60% as the subtitle; the
    /// user asked for it a touch lighter so it stands out, hence 72%.
    static let rowTime = Color(red: 235 / 255, green: 235 / 255, blue: 245 / 255).opacity(0.72)
    /// CSS `.day{color:#98989F}`: the day headers.
    static let dayHeader = Color(red: 0x98 / 255, green: 0x98 / 255, blue: 0x9F / 255)
    /// `#30D158` (iOS system green, dark): "Now" on a session still running.
    static let runningGreen = Color(red: 0x30 / 255, green: 0xD1 / 255, blue: 0x58 / 255)
}

private enum TimeTabMetrics {
    /// CSS `.sub{margin-top:6px}`.
    static let titleToSubtitleSpacing: CGFloat = 6
    /// CSS `.day{margin:32px 0 4px;letter-spacing:.06em}` at 13pt. The
    /// spinner and the empty state sit the same 32pt below the header.
    static let dayHeaderTopSpacing: CGFloat = 32
    static let dayHeaderBottomSpacing: CGFloat = 4
    static let dayHeaderTracking: CGFloat = 0.78
}

