import SwiftUI

/// One Time-tab session on a single line: its time ("9 AM – 5 PM"), the
/// activity it was tagged with as a colored chip ("🧠 Focus ⌄", or "Choose"
/// when untagged), and its length ("7h 59m", or a green "Now" while running).
/// The chip is the only tap target; tapping it opens the purpose editor through
/// `onChange`.
///
/// The time and length are derived from `source`, so no caller can hand this
/// row a label that disagrees with the session it renders. `activity` is the
/// session's purpose already resolved against the activity list by
/// `TimeTabView`, or nil when the purpose id is missing or unknown.
struct TimeTabRow: View {
    let source: TimeRowSource
    let activity: Activity?
    let onChange: () -> Void

    var body: some View {
        // Derived once here and used for both the visible labels and the
        // VoiceOver label, so the two always agree.
        let timeLabel = TimeDayGrouping.timeLabel(for: source)
        let lengthLabel = TimeDayGrouping.lengthLabel(for: source)
        let isRunning = TimeDayGrouping.spanSeconds(for: source) == nil

        HStack(spacing: TimeTabRowMetrics.itemSpacing) {
            Text(timeLabel)
                .dsFixedFont(.system(size: TimeTabRowMetrics.fontSize))
                .monospacedDigit()
                .foregroundStyle(TimeTabPalette.rowTime)
                .lineLimit(1)
                // A cross-meridiem range ("10:45 AM – 12:30 PM") is about
                // 150pt wide at 15pt; shrinking keeps it inside the column.
                .minimumScaleFactor(TimeTabRowMetrics.timeMinimumScale)
                .frame(width: TimeTabRowMetrics.timeColumnWidth, alignment: .leading)
                // The chip is the part that truncates when space runs out.
                .layoutPriority(1)

            chipButton
                // Pushes the length to the trailing edge, like the mock's
                // `margin-left:auto`, without adding to the 10pt gap.
                .frame(maxWidth: .infinity, alignment: .leading)

            Text(lengthLabel)
                .dsFixedFont(.system(size: TimeTabRowMetrics.fontSize, weight: .semibold))
                .monospacedDigit()
                .foregroundStyle(isRunning ? TimeTabPalette.runningGreen : TimeTabPalette.textPrimary)
                .fixedSize()
        }
        .padding(.vertical, TimeTabRowMetrics.verticalPadding)
        // VoiceOver reads the row as one button instead of three fragments.
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(
            "\(timeLabel), \(activityTitle ?? "No activity"), \(spokenLength). Change activity"
        )
        .accessibilityAddTraits(.isButton)
        .accessibilityAction { openEditor() }
    }

    // MARK: Chip

    /// The activity as a capsule in the color of its emoji, and the way into
    /// the purpose editor. The capsule is drawn 32pt tall but answers taps
    /// across 44pt.
    private var chipButton: some View {
        Button {
            openEditor()
        } label: {
            HStack(spacing: TimeTabRowMetrics.chipContentSpacing) {
                Text(chipLabel)
                    .dsFixedFont(.system(size: TimeTabRowMetrics.fontSize, weight: .semibold))
                    .lineLimit(1)
                Image(systemName: "chevron.down")
                    .dsFixedFont(.system(size: TimeTabRowMetrics.chevronSize, weight: .semibold))
            }
            .foregroundStyle(chipColor)
            .padding(.horizontal, TimeTabRowMetrics.chipHorizontalPadding)
            .frame(height: TimeTabRowMetrics.chipHeight)
            .background(Capsule().fill(chipColor.opacity(TimeTabRowMetrics.chipFillOpacity)))
            .frame(minHeight: DS.Spacing.minimumTouchTargetHeight)
            // Without this the capsule is the only hit-testable shape and the
            // rest of the 44pt box is untappable padding.
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
    }

    /// "🧠 Focus" for a known activity, the saved name alone ("Reading") when
    /// the activity is no longer in the list, and "Choose" when the session has
    /// no purpose at all.
    private var chipLabel: String {
        guard let activityTitle else { return "Choose" }
        guard let activity else { return activityTitle }
        return "\(activity.emoji) \(activityTitle)"
    }

    /// The color of the activity's emoji (🍳 yellow, 🧠 lavender), the same one
    /// the picker's selected tile wears. Periwinkle when there is no known
    /// activity to take it from: a saved name alone, or "Choose".
    private var chipColor: Color {
        guard let activity else { return DS.Colors.periwinkle }
        return ActivityEmojiPalette.color(forEmoji: activity.emoji)
    }

    /// The sentence-case title ("Being present"), or nil when the session has no
    /// purpose. A known activity uses its current name; otherwise the name
    /// saved on the session when it was tagged.
    private var activityTitle: String? {
        if let activity {
            return ActivityTitleForm.title(activity.name)
        }
        guard let savedName = TimeDayGrouping.purposeName(for: source), !savedName.isEmpty else {
            return nil
        }
        return ActivityTitleForm.title(savedName)
    }

    // MARK: Accessibility

    /// The length as VoiceOver should say it: "7 hours 59 minutes", "less than
    /// a minute", or "now" for a session still running.
    private var spokenLength: String {
        guard let span = TimeDayGrouping.spanSeconds(for: source) else { return "now" }
        if span < 60 {
            return "less than a minute"
        }
        return TimeFormatters.spokenDuration(minutes: span / 60)
    }

    private func openEditor() {
        Haptics.fire(.tap)
        onChange()
    }
}

/// Sizes read from the Time tab mock
/// (`.claude/plans/assets/2026-09-24-time-vv4-mock.html`).
private enum TimeTabRowMetrics {
    /// CSS `.one{gap:10px}`.
    static let itemSpacing: CGFloat = 10
    /// CSS `.one{padding:14px 0}` is measured from the 32pt capsule, but the
    /// chip answers taps across 44pt, so 6pt of that padding already sits
    /// inside the chip's hit area. Padding the remaining 8pt keeps the mock's
    /// 60pt row (8 + 44 + 8) with the capsule 14pt from each edge.
    static let verticalPadding: CGFloat = 8
    /// CSS `.one .t{width:112px}`, `font-size:15px` for the time, chip and length.
    static let timeColumnWidth: CGFloat = 112
    static let fontSize: CGFloat = 15
    static let timeMinimumScale: CGFloat = 0.7
    /// CSS `.chip{height:32px;padding:0 12px;gap:6px}` and the chip's 16% fill.
    static let chipHeight: CGFloat = 32
    static let chipHorizontalPadding: CGFloat = 12
    static let chipContentSpacing: CGFloat = 6
    static let chipFillOpacity: Double = 0.16
    /// The mock's chip ends in a text "⌄" about 11pt wide; a 13pt
    /// `chevron.down` draws at that width.
    static let chevronSize: CGFloat = 13
}
import SwiftUI

/// Sheet that edits the purpose FK + snapshot on either a completed
/// BlockSession OR a completed Quick Start CompletedFocusSession. It is the
/// shared tile picker with "No purpose" first, and tapping a tile saves it
/// right away (there is no Save button). The source-type tag drives the write
/// path.
///
/// A save that persists closes the sheet through `onSave`. A save that fails
/// keeps the sheet open on the tapped tile and shows an alert; tapping a tile
/// again retries. The close button leaves the purpose as it was.
struct SessionPurposeEditorView: View {
    let source: TimeRowSource
    let activities: [Activity]
    let onSave: () -> Void

    @Environment(\.dataStore) private var store
