import Foundation

// The analytics wire format the app owns. Every surface records an
// `AnalyticsEvent`; `AnalyticsHub` stamps it, applies the consent decision,
// and hands it to each `AnalyticsSink`. Swapping analytics providers means
// writing one new sink, never touching an instrumentation site.
//
// Foundation-only so the test target can pin the schema, and so the local
// funnel log (which persists these events verbatim) stays decodable
// without any provider SDK present.

/// One property value on an event. Deliberately small: providers take flat
/// scalar parameters, so an array or a nested object has no place to land.
enum AnalyticsValue: Codable, Equatable {
    case string(String)
    case int(Int)
    case double(Double)
    case bool(Bool)

    // Hand-written single-value coding, so the exported JSON is flat
    // (`"dwell_ms": 1200`). Synthesized `Codable` for an enum with associated
    // values would nest it as `{"int":{"_0":1200}}`, which no provider, and
    // no human reading the funnel log: can use.

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .string(let value): try container.encode(value)
        case .int(let value):    try container.encode(value)
        case .double(let value): try container.encode(value)
        case .bool(let value):   try container.encode(value)
        }
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        // Order matters. Bool first, because `true` must never come back as a
        // number; then Int before Double, because JSON has one number type and
        // the narrower case is the one every taxonomy property actually uses.
        // Consequence, accepted: an integral-valued `.double` such as 2.0
        // round-trips as `.int(2)`. No taxonomy property is a Double today,
        // and none may be added without a non-integral round-trip test value.
        if let value = try? container.decode(Bool.self) {
            self = .bool(value)
        } else if let value = try? container.decode(Int.self) {
            self = .int(value)
        } else if let value = try? container.decode(Double.self) {
            self = .double(value)
        } else {
            self = .string(try container.decode(String.self))
        }
    }
}

/// One analytics event: a name from `AnalyticsCatalog` plus its properties.
struct AnalyticsEvent: Codable, Equatable {
    let name: String
    let properties: [String: AnalyticsValue]

    init(name: String, properties: [String: AnalyticsValue] = [:]) {
        self.name = name
        self.properties = properties
    }

    /// A copy of this event carrying `additions` on top of its own properties.
    /// The event's own keys always win, so neither the hub's stamps nor a
    /// sticky cohort value can overwrite what the catalog constructor put
    /// there.
    func adding(_ additions: [String: AnalyticsValue]) -> AnalyticsEvent {
        guard !additions.isEmpty else { return self }
        var merged = additions
        merged.merge(properties) { _, own in own }
        return AnalyticsEvent(name: name, properties: merged)
    }
}

/// Per-install / per-process facts every sink receives alongside an event.
/// Deliberately short: app version, OS, device and accessibility settings are
/// attached automatically by the analytics provider, so duplicating them here
/// would ship the same fact twice.
struct AnalyticsContext: Equatable {
    /// The app's own random install identifier, or nil on an install that has
    /// never reached a sendable consent decision (so no id was ever minted).
    let installID: String?
    /// Stable for the life of the process, so events from one launch join.
    let sessionID: String
    /// True when this launch picked up a persisted onboarding resume blob.
    let resumed: Bool
    /// Whether this build opens onboarding with the hello splash.
    let helloSplash: Bool
    /// Bumped when the event schema changes shape in a way a consumer has to
    /// notice. Fixed at 1 for this release.
    let schemaVersion = 1
}

/// Sticky per-install answers that get merged onto every later event.
///
/// The analytics provider cannot join signals across a user, so a funnel or a
/// day-N retention cut "by goal" only works if the goal travels on each event
/// that should be cut by it. `AnalyticsHub` keeps the accumulated cohort and
/// runs these two pure functions on every tracked event.
enum CohortProperties {

    /// One event property whose value becomes a sticky cohort property.
    struct Source {
        /// The `AnalyticsCatalog` event name that carries the answer.
        let eventName: String
        /// The property key on that event.
        let eventKey: String
        /// The key the value is remembered and re-attached under.
        let cohortKey: String
    }

    /// The four profiling answers worth cutting every later event by. Event
    /// names are literals here because `AnalyticsCatalog` holds constructors
    /// and nothing else; `CohortPropertiesTests` pins each one against the
    /// catalog so a rename cannot silently orphan a cohort.
    static let sources: [Source] = [
        Source(eventName: "goal_selected", eventKey: "goal", cohortKey: "goal"),
        Source(eventName: "age_selected", eventKey: "age_bracket", cohortKey: "age_bracket"),
        Source(eventName: "profession_selected", eventKey: "profession", cohortKey: "profession"),
        Source(eventName: "screen_time_set", eventKey: "bucket", cohortKey: "screen_time_bucket"),
    ]

    /// The cohort after observing `event`. A non-source event leaves it
    /// unchanged; a repeated source answer replaces the earlier value.
    static func updated(_ cohort: [String: String], with event: AnalyticsEvent) -> [String: String] {
        guard
            let source = sources.first(where: { $0.eventName == event.name }),
            let property = event.properties[source.eventKey],
