            return cohort
        }
        var result = cohort
        result[source.cohortKey] = value
        return result
    }

    /// `event` with every cohort key it does not already carry attached.
    static func merged(_ event: AnalyticsEvent, cohort: [String: String]) -> AnalyticsEvent {
        event.adding(cohort.mapValues { AnalyticsValue.string($0) })
    }
