import Foundation
import Observation

/// The app's single analytics entry point.
///
/// Everything that measures anything calls `track(_:)` with an
/// `AnalyticsCatalog` event. The hub stamps it, applies the consent decision,
/// remembers the sticky cohort answers, and fans the result out to the sinks.
/// No instrumentation site ever sees a consent flag or a sink.
///
/// The three consent facts are stored here and persisted to the App Group,
/// so the decision reads the same during onboarding, after a resume, and long
/// after the flow is over. They are mutated only by `recordConsent()` and
/// `markAgeAnswered(bracket:)`, no other code in the app writes those keys.
@MainActor
@Observable
final class AnalyticsHub {

    static let shared = AnalyticsHub()

    /// The consent version the current welcome-screen wording records.
    private static let currentConsentVersion = 1

    /// Events held between the consent tap and the age answer. Small on
    /// purpose: onboarding reaches the age screen within a handful of events.
    private static let bufferCapacity = 64

    // MARK: - Consent state (persisted)

    /// 0 on an install that never saw the consent line, so it never uploads.
    private var consentVersion: Int
    private var minorLockout: Bool
    private var ageConfirmed: Bool

    /// The app's own random identifier for this install, minted the first time
    /// an event is actually sendable. Nil means nothing has ever been sent.
    private var installID: String?

    // MARK: - Plumbing

    private let store: SharedDataStore
    /// Held with its own type as well as in `sinks`, because opening an
    /// onboarding session is a local-log concern and not part of `AnalyticsSink`.
    private let localSink: LocalFunnelSink
    @ObservationIgnored private var sinks: [any AnalyticsSink]
    @ObservationIgnored private var bufferedEvents: [BufferedEvent] = []
    @ObservationIgnored private var cohort: [String: String]
    @ObservationIgnored private var resumed = false

    /// Stable for the life of the process, so a launch's events join to each
    /// other even after onboarding has ended.
    private let sessionID = UUID().uuidString
    /// Origin for every event's `t_offset_ms`: the moment this hub was first
    /// reached, which is the onboarding model's construction on a new install
    /// and the main app's first appearance afterwards.
    private let firstReachedAt = Date()

    private struct BufferedEvent {
        let event: AnalyticsEvent
        let timestamp: Date
    }

    /// Private so the persisted consent keys have exactly one owner: a second
    /// hub would hydrate the same keys into a second, diverging copy.
    private init() {
        let store = SharedDataStore.shared
        self.store = store

        consentVersion = store.getInt(forKey: SharedConstants.Keys.analyticsConsentVersion)
        minorLockout = store.defaultsBool(
            forKey: SharedConstants.Keys.analyticsMinorLockout,
            fallback: false
        )
        ageConfirmed = store.defaultsBool(
            forKey: SharedConstants.Keys.analyticsAgeConfirmed,
            fallback: false
        )
        installID = store.getString(forKey: SharedConstants.Keys.analyticsInstallID)
        cohort = Self.loadCohort(from: store)

        let localSink = LocalFunnelSink()
        self.localSink = localSink
        // Constructing the provider sink starts nothing: it reaches its SDK
        // only once an event has passed the consent decision.
        sinks = [localSink, TelemetryDeckSink()]
    }

    // MARK: - Recording

    /// Records `event`. Whether it is dropped, buffered, or sent is entirely
    /// the consent decision's business: callers never check.
    func track(_ event: AnalyticsEvent) {
        let timestamp = Date()
        let stampedEvent = stamped(event, at: timestamp)

        switch currentDecision {
        case .drop:
            // Nothing is kept for an install the gate refused, not even the
            // cohort, which would otherwise persist an answer from a minor or
            // a grandfathered user.
            return
        case .buffer:
            rememberCohort(from: stampedEvent)
            buffer(CohortProperties.merged(stampedEvent, cohort: cohort), at: timestamp)
        case .send:
            rememberCohort(from: stampedEvent)
            deliver(CohortProperties.merged(stampedEvent, cohort: cohort), at: timestamp)
        }
    }

    /// Runs one "report once" rule from `UsageMarkerRules` and sends what it
    /// decided: loads the stored markers, saves the rule's new markers (only
    /// when they changed) BEFORE tracking its events, then tracks them.
    ///
    /// Does nothing unless `canSend`, so an install that never consented never
    /// reads or writes the markers. With consent it does read them, and it
    /// saves baselines on passes that send nothing. Holds no copy of them
    /// between calls: three call sites write different fields of the one
    /// stored value, and a copy kept here could undo one of them or a Delete
    /// All Data.
    func reportUsage(_ rule: (AnalyticsUsageMarkers) -> UsageMarkerUpdate) {
        guard canSend else { return }
        let markers = loadUsageMarkers()
        let update = rule(markers)
        if update.markers != markers {
            saveUsageMarkers(update.markers)
        }
        for event in update.events {
            track(event)
        }
    }

    /// Opens the local diagnostics log's session for this launch of the
    /// onboarding flow. Deliberately not consent-gated: the events inside it
    /// still are, but a suppressed header would swallow the whole log.
    func beginOnboardingSession(resumed: Bool) {
        self.resumed = resumed
        localSink.beginOnboardingSession(resumed: resumed)
    }

    // MARK: - Consent

    /// Continuing past the welcome screen, whose copy states it, is consent.
    func recordConsent() {
        // Keeps the recorded version monotonic: a rolled-back build must never
        // write 1 over a stored 2.
        guard consentVersion < Self.currentConsentVersion else { return }
        consentVersion = Self.currentConsentVersion
        store.setInt(consentVersion, forKey: SharedConstants.Keys.analyticsConsentVersion)
    }

    /// Resolves the install the moment the age chip is tapped: before the
    /// screen advances, so a 13–17 answer can never be followed by a send.
    func markAgeAnswered(bracket: OnboardingAgeBracket) {
        if bracket.lowerBoundAge < 18 {
            lockOutMinor()
        } else {
            confirmAdult()
        }
    }

    /// True when an event tracked right now would reach the sinks.
    var canSend: Bool { currentDecision == .send }

    private var currentDecision: AnalyticsConsent.Decision {
        AnalyticsConsent.decision(
            consentVersion: consentVersion,
            minorLockout: minorLockout,
            ageConfirmed: ageConfirmed
        )
    }

    /// Nothing further is ever sent for this install, and the buffer goes with
    /// the answer. Every sink is stopped as well: a sink that has already
    /// started keeps reporting on its own otherwise.
    private func lockOutMinor() {
        minorLockout = true
        store.setBool(true, forKey: SharedConstants.Keys.analyticsMinorLockout)
        bufferedEvents.removeAll()
        for sink in sinks {
            sink.stop()
        }
    }

    private func confirmAdult() {
        ageConfirmed = true
        store.setBool(true, forKey: SharedConstants.Keys.analyticsAgeConfirmed)
        releaseBuffer()
    }

    /// The only place the buffer is drained. Keeping it here, rather than on
    /// a general-purpose flush, means events held before the age answer can
    /// leave exactly once, by the one path that resolved the install.
    private func releaseBuffer() {
        guard currentDecision == .send else { return }
        let pending = bufferedEvents
        bufferedEvents.removeAll()
        for buffered in pending {
            deliver(buffered.event, at: buffered.timestamp)
        }
    }

    // MARK: - Identity

    /// Minted only when an event is actually about to be sent, so an install
    /// that never consents never gets an identifier at all.
    private func mintInstallIDIfNeeded() {
        guard installID == nil else { return }
        installID = mintInstallID()
    }

    private func mintInstallID() -> String {
        let freshID = UUID().uuidString
        store.setString(freshID, forKey: SharedConstants.Keys.analyticsInstallID)
        return freshID
    }

    // MARK: - Delivery

    /// The two properties every event carries whatever built it. Stamped
    /// before the consent decision, so a buffered event keeps the identity and
    /// the offset it had at the moment it happened.
    private func stamped(_ event: AnalyticsEvent, at timestamp: Date) -> AnalyticsEvent {
        event.adding([
            "event_id": .string(UUID().uuidString),
            "t_offset_ms": .int(Int(timestamp.timeIntervalSince(firstReachedAt) * 1000))
        ])
    }

    private func buffer(_ event: AnalyticsEvent, at timestamp: Date) {
        // Drop-newest at the cap. The head of the funnel is the reason this
        // buffer exists, so evicting it to make room would defeat the point.
        guard bufferedEvents.count < Self.bufferCapacity else { return }
        bufferedEvents.append(BufferedEvent(event: event, timestamp: timestamp))
    }

    private func deliver(_ event: AnalyticsEvent, at timestamp: Date) {
        mintInstallIDIfNeeded()
        let context = AnalyticsContext(
            installID: installID,
            sessionID: sessionID,
            resumed: resumed,
            helloSplash: OnboardingFlow.includesHelloSplash
        )
        for sink in sinks {
            sink.send(event, at: timestamp, context: context)
        }
    }

    // MARK: - Cohort

    private func rememberCohort(from event: AnalyticsEvent) {
        let updated = CohortProperties.updated(cohort, with: event)
        guard updated != cohort else { return }
        cohort = updated
        guard
            let data = try? JSONEncoder().encode(updated),
            let json = String(data: data, encoding: .utf8)
        else {
            return
        }
        store.setString(json, forKey: SharedConstants.Keys.analyticsCohort)
    }

    // MARK: - Usage markers

    /// Markers that are missing or unreadable decode as "no baseline yet" for
    /// every field, which is the safe answer: the next rule records where
    /// things stand and reports nothing that needed a previous value.
    private func loadUsageMarkers() -> AnalyticsUsageMarkers {
        guard
            let json = store.getString(forKey: SharedConstants.Keys.analyticsUsageMarkers),
            let data = json.data(using: .utf8),
            let markers = try? JSONDecoder().decode(AnalyticsUsageMarkers.self, from: data)
        else {
            return AnalyticsUsageMarkers()
        }
        return markers
    }

    private func saveUsageMarkers(_ markers: AnalyticsUsageMarkers) {
        guard
            let data = try? JSONEncoder().encode(markers),
            let json = String(data: data, encoding: .utf8)
        else {
            return
        }
        store.setString(json, forKey: SharedConstants.Keys.analyticsUsageMarkers)
    }

    private static func loadCohort(from store: SharedDataStore) -> [String: String] {
        guard
            let json = store.getString(forKey: SharedConstants.Keys.analyticsCohort),
            let data = json.data(using: .utf8),
            let cohort = try? JSONDecoder().decode([String: String].self, from: data)
        else {
            return [:]
        }
        return cohort
    }
}
