/// The compile-time fence that keeps the analytics provider's SDK out of the
/// simulator and UI-only builds.
///
/// `ScreenTime-UIOnly` never links the package, so a stray provider call in any
/// other file simply fails to build; that build is the fence everywhere else.
/// `TelemetryDeckSink.swift` is the one file that *does* name the SDK, so its
/// shape is pinned here instead: the fence must be the first thing in the file,
/// and nothing that touches the SDK may sit in the stub branch below `#else`.
///
/// Pinned at the source because a compiled test can only observe the build it
/// runs in, and the build it runs in is the one that never links the SDK. Same
/// source-reading approach as `ProGatingReadsAtAccessSiteTests`.
final class AnalyticsSourceFenceTests: XCTestCase {

    private static let sinkSourcePath =
        "/Users/antonioperedo/Desktop/screen_time/ScreenTime/Sources/App/Core/Analytics/TelemetryDeckSink.swift"

    private static let fenceLine = "#if !targetEnvironment(simulator) && !UI_ONLY"

    private func sinkSourceLines() throws -> [String] {
        let source = try String(contentsOfFile: Self.sinkSourcePath, encoding: .utf8)
        return source.components(separatedBy: .newlines).map {
            $0.trimmingCharacters(in: .whitespaces)
        }
    }

    func test_theFenceIsTheFirstCodeInTheFile() throws {
        let lines = try sinkSourceLines()
        let firstCodeLine = lines.first { !$0.isEmpty && !$0.hasPrefix("//") }

        XCTAssertEqual(
            firstCodeLine,
            Self.fenceLine,
            "TelemetryDeckSink.swift must open with the fence. Anything above it (an import especially) compiles into the simulator and UI-only builds."
        )
    }

    func test_theProviderIsImportedInsideTheFence() throws {
        let lines = try sinkSourceLines()
        let fenceIndex = try XCTUnwrap(lines.firstIndex(of: Self.fenceLine))
        let importIndex = try XCTUnwrap(
            lines.firstIndex(of: "import TelemetryDeck"),
            "TelemetryDeckSink.swift no longer imports the provider SDK"
        )

        XCTAssertGreaterThan(
            importIndex,
            fenceIndex,
            "`import TelemetryDeck` must sit inside the fenced branch"
        )
    }

    func test_nothingBelowTheElseTouchesTheProviderSDK() throws {
        let lines = try sinkSourceLines()
        let elseIndexes = lines.indices.filter { lines[$0] == "#else" }

        XCTAssertEqual(
            elseIndexes.count,
            1,
            "TelemetryDeckSink.swift is meant to be one fence with one stub branch"
        )
        let elseIndex = try XCTUnwrap(elseIndexes.first)

        let sdkLinesBelowElse = lines.indices
            .filter { $0 > elseIndex && lines[$0].contains("TelemetryDeck.") }
            .map { "line \($0 + 1): \(lines[$0])" }

        XCTAssertTrue(
            sdkLinesBelowElse.isEmpty,
            "the stub branch must never name the SDK, not even in a comment, which would read as a call that got moved: \(sdkLinesBelowElse)"
        )
    }
}
