final class TimeTabReviewTests: XCTestCase {

    private let actWork = UUID()
    private let actRead = UUID()

    /// Builds a completed block whose planned/actual window length EQUALS
    /// `effective` seconds (ending at `end`). Under the single-derivation model,
    /// effective time is re-derived from the window minus actual bypasses (not
    /// read from the stored `effectiveSeconds` scalar), so a no-bypass block's
    /// net == its window length: making `effective` the net total. `nil`
    /// effective (legacy) keeps a default window but is excluded by
    /// `CountableSession`; `0` yields an empty window (a fully-broken block).
    private func block(
        purpose: UUID?,
        name: String?,
        effective: Int?,
        end: Date,
        id: UUID = UUID()
    ) -> BlockSession {
        let windowLength = TimeInterval(max(0, effective ?? 3600))
        let start = end.addingTimeInterval(-windowLength)
        return BlockSession(
            id: id,
            scheduleID: UUID(),
            scheduleNameSnapshot: "Schedule",
            plannedStart: start,
            plannedEnd: end,
            actualStart: start,
            actualEnd: end,
            purposeActivityID: purpose,
            purposeActivityNameSnapshot: name,
            breakSeconds: nil,
            effectiveSeconds: effective,
            status: .completed
        )
    }

    private func quick(
        purpose: UUID?,
