import XCTest

/// Wiring guardrail for the Time tab's 14-day window.
///
/// `LiveSnapshotBuilder.computeTabsExtraSnapshot` feeds two tabs from one pass:
/// the Time tab lists the last 14 days (`TimeDayGrouping.completedRowsInWindow`),
/// while the Activities tab's grouped totals stay on the last 7 days. The
/// builder is App-target-only (not compiled into the test target), so
/// `TimeDayGroupingWindowTests` can prove the filter but not that the builder
/// calls it, nor that the 14-day sets stay out of the Activities groups. This
/// pins both at the source, the same pattern `ActivitiesFeedSourceTests` uses.
final class TimeTabWindowSourceTests: XCTestCase {

    private let liveSnapshotBuilderPath =
        "/Users/antonioperedo/Desktop/screen_time/ScreenTime/Sources/App/Core/LiveSnapshotBuilder.swift"

    /// `computeTabsExtraSnapshot` is the file's last function, so everything
    /// from its name to the end of the file is its body.
    private func computeTabsExtraSnapshotSource() throws -> String {
        let source = try String(contentsOfFile: liveSnapshotBuilderPath, encoding: .utf8)
        guard let regionStart = source.range(of: "static func computeTabsExtraSnapshot") else {
            XCTFail("`computeTabsExtraSnapshot` is gone from LiveSnapshotBuilder.swift: the Time window moved without updating this guardrail.")
            return ""
        }
        return String(source[regionStart.lowerBound...])
    }

    /// The text of one call: from `callName` (which ends with the opening
    /// parenthesis) through the parenthesis that closes it. Nil when the call is
    /// absent or never closes.
    private func callText(_ callName: String, in source: String) -> String? {
        guard let nameRange = source.range(of: callName) else { return nil }
        var openParenthesisCount = 1
        var index = nameRange.upperBound
        while index < source.endIndex {
            if source[index] == "(" {
                openParenthesisCount += 1
            } else if source[index] == ")" {
                openParenthesisCount -= 1
                if openParenthesisCount == 0 {
                    return String(source[nameRange.lowerBound...index])
                }
            }
            index = source.index(after: index)
        }
        return nil
    }

    func test_timeRows_areBuiltByTheFourteenDayWindowFilter() throws {
        let region = try computeTabsExtraSnapshotSource()

        // The call's arguments matter as much as the call: handing it the
        // 7-day sets would still compile, still call the filter, and still
        // leave the Time tab at 7 days. They are checked inside the call's own
        // text because the same argument strings also appear in other calls in
        // this function (`ActivityAggregation.loadFingerprint(`), so a
        // whole-function search could never fail.
        let filterCall = try XCTUnwrap(
            callText("TimeDayGrouping.completedRowsInWindow(", in: region),
            "The Time rows must come from `TimeDayGrouping.completedRowsInWindow`; without the call the Time tab never reaches past 7 days."
        )
        XCTAssertTrue(
            filterCall.contains("blocks: inputs.completedBlockSessions,"),
            "The Time rows' filter must receive the full completed block sessions (`inputs.completedBlockSessions`), not the 7-day set."
        )
        XCTAssertTrue(
            filterCall.contains("quick: inputs.completedFocusSessions,"),
            "The Time rows' filter must receive the full completed Quick Starts (`inputs.completedFocusSessions`), not the 7-day set."
        )
        XCTAssertFalse(
            region.contains("sevenDayBlocks.map(TimeRowSource.scheduledBlock)"),
            "The Time rows are built from the 7-day block set again, so the Time tab is back to 7 days."
        )
    }

    func test_activitiesGroups_stayOnTheSevenDaySets() throws {
        let region = try computeTabsExtraSnapshotSource()

        let sevenDayPins = [
            "rollingCutoff(now: now, days: 7)",
            "inputs.completedBlockSessions.filter { ($0.actualEnd ?? .distantPast) >= sevenDayCutoff }",
            "inputs.completedFocusSessions.filter { $0.endTime >= sevenDayCutoff }",
            "sevenDayBlocks: sevenDayBlocks,",
            "window: (sevenDayCutoff, now)",
        ]
        for pin in sevenDayPins {
            XCTAssertTrue(
                region.contains(pin),
                "The Activities grouped totals must stay on the 7-day sets, but `\(pin)` is gone from `computeTabsExtraSnapshot`; the 14-day Time window must not leak into them."
            )
        }
    }
}
