/// Wiring guardrail for the Activities chart's data source.
///
/// Bug shape (commit `3edea86`, "P4-g"): `TimelineSnapshot`'s session arrays
/// were bounded to records overlapping TODAY so the Block List timeline card's
/// per-minute rebuild would stay O(today). The Activities tab was reading those
/// same arrays through the shared bundle, so every chart window older than
/// today silently totalled 0, no test observed the tab's feed.
///
/// The fix severs the read: the tab is fed the full-history arrays that ride
/// `TabsSpineSnapshot`, and holds no reference to the timeline bundle at all.
/// `LiveSnapshotBuilder` and `ActivitiesTabView` are App-target-only (not
/// compiled into the test target) and SwiftUI wiring is not driveable from
/// XCTest, so the severance is pinned at the source: the same pattern
/// `ProGatingReadsAtAccessSiteTests` uses.
///
/// The last two cases pin the live tail the chart folds on top of that archive:
/// its no-elongation clamp, and the simulator mock that makes the fold visible
/// off-device.
final class ActivitiesFeedSourceTests: XCTestCase {

    private let activitiesTabViewPath =
        "/Users/antonioperedo/Desktop/screen_time/ScreenTime/Sources/App/Features/Activities/ActivitiesTabView.swift"
    private let liveSnapshotBuilderPath =
        "/Users/antonioperedo/Desktop/screen_time/ScreenTime/Sources/App/Core/LiveSnapshotBuilder.swift"
    private let activityChartCardPath =
        "/Users/antonioperedo/Desktop/screen_time/ScreenTime/Sources/App/Features/Activities/ActivityChartCard.swift"
    private let mainTabViewPath =
        "/Users/antonioperedo/Desktop/screen_time/ScreenTime/Sources/App/Core/MainTabView.swift"

    private func loadSource(at path: String) throws -> String {
        return try String(contentsOfFile: path, encoding: .utf8)
    }

    // MARK: - The tab never reads the today-bounded timeline bundle

    func test_activitiesTabView_doesNotReadTheTodayBoundedTimelineInputs() throws {
        let source = try loadSource(at: activitiesTabViewPath)

        // Both spellings: `timelineInputs` is the pre-rename name and
        // `todayBoundedInputs` the current one. Either token appearing here
        // means the tab is coupled to the Block List card's bounded feed again.
        XCTAssertFalse(
            source.contains("timelineInputs"),
            "3edea86 regression: ActivitiesTabView reads `timelineInputs` again; those arrays are bounded to today, so every chart window older than today totals 0."
        )
        XCTAssertFalse(
            source.contains("todayBoundedInputs"),
            "3edea86 regression: ActivitiesTabView reads `todayBoundedInputs`; those arrays are bounded to today, so every chart window older than today totals 0."
        )
    }

    func test_activitiesTabView_feedsTheChartFromTheSpineArchive() throws {
        let source = try loadSource(at: activitiesTabViewPath)

        XCTAssertTrue(
            source.contains("tabsSpine.activitiesBlockSessions"),
            "ActivitiesTabView must feed the chart from `tabsSpine.activitiesBlockSessions`: the full session archive, not a today-bounded slice."
        )
    }

    // MARK: - The spine slice is sourced from the unbounded loaded inputs

    func test_computeTabsExtraSnapshot_sourcesTheArchiveFromTheLoadedInputs() throws {
        let source = try loadSource(at: liveSnapshotBuilderPath)
        guard let regionStart = source.range(of: "static func computeTabsExtraSnapshot") else {
            return XCTFail("`computeTabsExtraSnapshot` is gone from LiveSnapshotBuilder.swift: the Activities feed moved without updating this guardrail.")
        }
        let region = String(source[regionStart.lowerBound...])

        // The field-assignment form is what discriminates: the function already
        // reads `inputs.completedBlockSessions` for the Time rows, so a bare
        // substring pin could never fail. Any indirection (an intermediate
        // local, or re-sourcing from the timeline bundle) breaks this.
        XCTAssertTrue(
            region.contains("activitiesBlockSessions: inputs.completedBlockSessions"),
            "3edea86 regression: the Activities spine field is no longer assigned straight from `inputs.completedBlockSessions`, if it is re-sourced from the today-bounded timeline arrays, every chart window older than today totals 0."
        )
    }

    // MARK: - The live tail is clamped, and the simulator actually renders it

    /// The chart folds the running source in as a synthetic finalized record
    /// clamped at its planned end (no elongation). That clamp lives in a SwiftUI
    /// view's detached page build, which unit tests cannot drive, so it is
    /// pinned at the source like the wiring above.
    func test_activityChartCard_clampsTheLiveTailAtThePlannedEnd() throws {
        let source = try loadSource(at: activityChartCardPath)

        XCTAssertTrue(
            source.contains("min(now, liveSource.plannedEnd)"),
            "The Activities live tail must be clamped with `min(now, liveSource.plannedEnd)`, without it a synthetic record could count past the source's planned end (accounting invariant 2: no elongation)."
        )
    }

    /// The simulator's Activities tab is the only place the live fold can be
    /// verified off-device. `TabsSpineSnapshot.activitiesLiveSource` is an
    /// Optional `var`, so Swift hands every construction site an implicit `nil`
    /// default: dropping it here compiles, builds, and passes the suite while
    /// the feature quietly disappears from the simulator. Hence this pin.
    func test_mainTabView_simulatorActivitiesBranchPassesAMockLiveSource() throws {
        let source = try loadSource(at: mainTabViewPath)

        XCTAssertTrue(
            source.contains("ActivitiesLiveSource(start: MockData.mockActiveBlock.startDate"),
            "The simulator Activities branch must pass a mock `ActivitiesLiveSource` built from `MockData.mockActiveBlock`: an omitted field silently defaults to nil and the chart's live tail becomes unverifiable off-device."
        )
    }
}
